import{_ as r,o as t,c as o,a2 as a}from"./chunks/framework.ChTAMbUy.js";const s="/docs/assets/landing-page-with-server-list-and-catalogue.Ci5O4CtB.png",n="/docs/assets/playwright-launch-dialog.D-PDhIIA.png",i="/docs/assets/playwright-overview.sHWdH1cm.png",l="/docs/assets/playwright-live-browser-viewer.C56hqOwb.png",d="/docs/assets/playwright-details-metrics.lcgsfhPE.png",c="/docs/assets/playwright-details-logs.BiI5ZhDj.png",y=JSON.parse('{"title":"MCP Servers","description":"","frontmatter":{},"headers":[],"relativePath":"development/agentops/mcp_servers.md","filePath":"versions/development/agentops/mcp_servers.md","lastUpdated":1787837970000}'),p={name:"development/agentops/mcp_servers.md"};function h(u,e,g,m,v,b){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="mcp-servers" tabindex="-1">MCP Servers <a class="header-anchor" href="#mcp-servers" aria-label="Permalink to &quot;MCP Servers&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Upstream documentation</p><p>For MCP and ToolHive concepts that are not specific to prokube, use the upstream documentation:</p><ul><li><a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">Model Context Protocol documentation</a></li><li><a href="https://docs.stacklok.com/toolhive/" target="_blank" rel="noreferrer">ToolHive documentation</a></li><li><a href="https://docs.stacklok.com/toolhive/reference/crds/" target="_blank" rel="noreferrer">ToolHive Kubernetes CRD reference</a></li></ul></div><p>MCP servers expose tools, data sources, and internal APIs to AI assistants through the Model Context Protocol. In prokube, MCP servers run as Kubernetes workloads managed by ToolHive instead of local processes on a developer machine.</p><p>Use MCP servers when an agent or MCP-capable client needs governed access to a tool, for example sandbox execution, browser automation, databases, internal APIs, or other services that should not be called with broad user credentials.</p><h2 id="how-prokube-runs-mcp-servers" tabindex="-1">How prokube Runs MCP Servers <a class="header-anchor" href="#how-prokube-runs-mcp-servers" aria-label="Permalink to &quot;How prokube Runs MCP Servers&quot;">​</a></h2><p>Open <strong>MCP</strong> from the prokube UI sidebar under <strong>AgentOps</strong>. Select the workspace before deploying or inspecting servers.</p><p>An MCP server is deployed into the selected workspace namespace as a <a href="https://docs.stacklok.com/toolhive/reference/crds/" target="_blank" rel="noreferrer">ToolHive <code>MCPServer</code></a> resource. prokube provides the UI, workspace authorization, registry integration, logs, events, metrics, and optional Agent Gateway access. ToolHive handles the server runtime and local MCP proxy for that resource.</p><p>The MCP page contains two main sections:</p><ul><li><strong>Deployed Servers</strong>: MCP servers currently running in the selected workspace.</li><li><strong>Server Catalog</strong>: registry entries that can be deployed with preconfigured images, tools, metadata, and required configuration fields.</li></ul><p><img src="'+s+'" alt="MCP Servers page with deployed servers and server catalog" loading="lazy"></p><h2 id="deploy-from-the-catalog" tabindex="-1">Deploy from the Catalog <a class="header-anchor" href="#deploy-from-the-catalog" aria-label="Permalink to &quot;Deploy from the Catalog&quot;">​</a></h2><p>Use the catalog for known server images and common integrations. Catalog cards show the server name, description, provided tools, source, tier, repository link, and compatibility badges such as <strong>Requires Root</strong>.</p><p>The catalog can be filtered by:</p><ul><li>search text;</li><li>tier: <strong>Official</strong> or <strong>Community</strong>;</li><li>source: <strong>prokube.ai Only</strong> or <strong>Third Party Only</strong>;</li><li>sort order: stars or name.</li></ul><p>Click a catalog card to deploy it. The deploy dialog shows:</p><ul><li><strong>Namespace</strong>: target workspace namespace.</li><li><strong>Server Name</strong>: Kubernetes resource name for the MCP server.</li><li><strong>Configuration</strong>: required and optional environment variables from the registry entry.</li><li><strong>Registry Credentials</strong>: image pull secrets available in the workspace.</li><li><strong>Resource Limits</strong>: optional CPU and memory requests and limits.</li><li><strong>Technical Details</strong>: image, transport, and provided tools.</li></ul><p><img src="'+n+'" alt="Deploy dialog for a catalog MCP server" loading="lazy"></p><p>Environment variables can be entered directly or read from a Kubernetes Secret in the workspace. Use Secrets for tokens, passwords, API keys, and other sensitive values. See <a href="./../platform/kubernetes.html#kubernetes-secrets">Kubernetes Secrets</a>.</p><h3 id="catalog-source-and-trust" tabindex="-1">Catalog Source and Trust <a class="header-anchor" href="#catalog-source-and-trust" aria-label="Permalink to &quot;Catalog Source and Trust&quot;">​</a></h3><p>prokube uses the upstream <a href="https://github.com/stacklok/toolhive-catalog" target="_blank" rel="noreferrer">ToolHive Catalog</a>, a community-curated registry of MCP servers and skills. The catalog gives you a better starting point than searching for arbitrary container images: entries are described in a common format, reviewed through the ToolHive project, and include metadata such as the publisher, repository, required configuration, tools, and maintenance tier.</p><p>Treat the catalog as a curated trust signal, not as a blanket approval for every environment:</p><ul><li><strong>Official</strong> entries are maintained by the MCP team, the upstream project, or platform owners.</li><li><strong>Community</strong> entries are contributed and maintained by the community.</li><li><strong>prokube.ai Only</strong> narrows the list to entries published or curated by prokube.ai where available.</li></ul><p>Before giving an MCP server credentials or access to internal systems, still review what it connects to, who maintains it, which tools it exposes, and whether it needs broad permissions. Prefer Official or internally maintained servers for production workflows.</p><h2 id="deploy-a-custom-server" tabindex="-1">Deploy a Custom Server <a class="header-anchor" href="#deploy-a-custom-server" aria-label="Permalink to &quot;Deploy a Custom Server&quot;">​</a></h2><p>Use <strong>Deploy Custom Server</strong> when the server is not in the catalog or when you maintain your own image.</p><p>Required fields:</p><ul><li><strong>Server Name</strong>: Kubernetes-compatible resource name.</li><li><strong>Container Image</strong>: image that runs the MCP server.</li><li><strong>Transport Protocol</strong>: <code>stdio</code>, <code>sse</code>, or <code>streamable-http</code>.</li><li><strong>Proxy Port</strong>: port exposed by the ToolHive proxy.</li></ul><p>Optional fields:</p><ul><li>environment variables, either direct values or Secret references;</li><li>image pull credentials for private registries;</li><li>CPU and memory requests and limits;</li><li>container arguments;</li><li>root or writable-filesystem options for images that require them;</li><li>persistent storage for servers that need data to survive pod restarts;</li><li>live view for browser-based servers such as noVNC-backed Playwright images.</li></ul><p>Prefer custom images that run as non-root and work with a read-only root filesystem. Images that require root or write access are harder to run in restricted workspaces and have a larger security footprint.</p><h2 id="use-yaml-for-advanced-configuration" tabindex="-1">Use YAML for Advanced Configuration <a class="header-anchor" href="#use-yaml-for-advanced-configuration" aria-label="Permalink to &quot;Use YAML for Advanced Configuration&quot;">​</a></h2><p>As with other Kubernetes-backed resources in prokube, you can use YAML when the form does not expose a setting you need.</p><p>The deploy dialog can generate a ToolHive <code>MCPServer</code> manifest from the form fields. Use it to inspect the resource before deployment, adjust advanced fields, or submit a reviewed manifest directly through the UI.</p><p>The namespace is set by prokube to the selected workspace namespace. Custom YAML must still be a ToolHive <code>MCPServer</code> resource using a supported <code>toolhive.stacklok.dev</code> API version.</p><h2 id="connect-clients" tabindex="-1">Connect Clients <a class="header-anchor" href="#connect-clients" aria-label="Permalink to &quot;Connect Clients&quot;">​</a></h2><p>The <strong>Deployed Servers</strong> table shows each server&#39;s status, image, transport, proxy port, and URL when available. Deploying an MCP server also registers it with the workspace&#39;s federated MCP endpoint in Agent Gateway.</p><p><img src="'+i+'" alt="MCP server overview with external and internal connection details" loading="lazy"></p><p>For external clients, create an <a href="./../platform/api_keys.html">API key</a> scoped to the MCP server. Use the authentication format expected by the client.</p><p>For kagent agents, open <strong>Agents</strong> and select the discovered MCP tools when creating or editing the agent. Tools from workspace MCP servers appear through the managed <code>gateway-mcp</code> endpoint; create a separate Tool only when you need to connect an additional external MCP endpoint.</p><p>OpenCode and other MCP-capable clients can use the endpoint URL shown in prokube. In OpenCode Labs, add it through the OpenCode MCP manager and configure the required headers or OAuth settings there. See <a href="./../labs/opencode.html#add-mcp-servers">OpenCode: Add MCP Servers</a>.</p><h2 id="sandbox-mcp" tabindex="-1">Sandbox MCP <a class="header-anchor" href="#sandbox-mcp" aria-label="Permalink to &quot;Sandbox MCP&quot;">​</a></h2><p>The catalog includes <code>sandbox-mcp</code>, a prokube-provided MCP server for Agent Sandbox operations.</p><p>It exposes tools for common sandbox tasks, including creating sandboxes, claiming existing sandboxes, running commands, executing code, reading and writing files, and managing sandbox pools.</p><p>When deploying <code>sandbox-mcp</code>, prokube pre-fills deployment context for the selected workspace:</p><ul><li><code>PROKUBE_API_URL</code>: backend API URL reachable from the MCP server pod;</li><li><code>PROKUBE_WORKSPACE</code>: selected workspace namespace;</li><li><code>PROKUBE_USER_ID</code>: current user identity used for backend authorization.</li></ul><p>You can also set <code>SANDBOX_NAME</code> to auto-connect to a specific sandbox on the first tool call.</p><h2 id="browser-automation-servers" tabindex="-1">Browser Automation Servers <a class="header-anchor" href="#browser-automation-servers" aria-label="Permalink to &quot;Browser Automation Servers&quot;">​</a></h2><p>Some catalog entries, such as the prokube Playwright noVNC image, include live browser viewing and trace support.</p><p>For these servers, the details page can show:</p><ul><li><strong>Live View</strong> for an interactive browser session;</li><li><strong>Traces</strong> for recorded Playwright sessions;</li><li><strong>Logs</strong> and <strong>Events</strong> for debugging startup and runtime issues;</li><li><strong>Metrics</strong> for runtime monitoring.</li></ul><p><img src="'+l+'" alt="Live browser view for a browser automation MCP server" loading="lazy"></p><p><img src="'+d+'" alt="MCP server metrics for a browser automation server" loading="lazy"></p><p>Live view is only available for servers that declare live-view support in the catalog or custom configuration.</p><h2 id="security-and-operations" tabindex="-1">Security and Operations <a class="header-anchor" href="#security-and-operations" aria-label="Permalink to &quot;Security and Operations&quot;">​</a></h2><ul><li>Deploy servers only in workspaces where the intended users should have access to the exposed tools.</li><li>Store sensitive configuration in <a href="./../platform/kubernetes.html#kubernetes-secrets">Kubernetes Secrets</a> instead of direct environment variable values.</li><li>Prefer <strong>Official</strong> or internally maintained catalog entries for production use.</li><li>Review third-party images before granting access to internal data or network destinations.</li><li>Avoid root and writable-root-filesystem options unless the image requires them.</li><li>Restricted workspace security policies can reject servers that request root privileges.</li><li>Set resource requests and limits for long-running or shared servers.</li><li>Delete MCP servers that are no longer used.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>Server stays <code>Pending</code></td><td>Open the details page and check <strong>Events</strong> and <strong>Logs</strong>. Also verify image pull credentials and workspace quota.</td></tr><tr><td>Image cannot be pulled</td><td>Confirm the image name and select the required registry credential for private registries. See <a href="./../platform/kubernetes.html#registry-credentials">Registry Credentials</a>.</td></tr><tr><td>Deployment is rejected by security policy</td><td>The image may require root or a writable filesystem in a restricted workspace. Use a compliant image or ask an administrator to review the workspace policy.</td></tr><tr><td>Required configuration is missing</td><td>Check the catalog entry&#39;s required environment variables and provide direct values or Secret references.</td></tr><tr><td>Client cannot connect</td><td>Confirm the server is <code>Running</code>, copy the current URL, and verify the API key is scoped to the MCP server.</td></tr><tr><td>Tool calls fail after connecting</td><td>Check server logs, required upstream credentials, workspace network policy, and whether the tool depends on an external service.</td></tr></tbody></table><p><img src="'+c+'" alt="MCP server logs for a browser automation server" loading="lazy"></p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./../platform/api_keys.html">API Keys</a></li><li><a href="./../platform/kubernetes.html">Kubernetes Resources</a></li><li><a href="./sandboxes.html">Agent Sandboxes</a></li><li><a href="./agents.html">Agents</a></li></ul>',60)])])}const w=r(p,[["render",h]]);export{y as __pageData,w as default};
